// Model files are generated by build.rs when Cargo builds the application.
include!(concat!(env!("OUT_DIR"), "/models.rs"));

/// Returns the raw bytes of a bundled model, by its path relative to models/
/// (e.g. "props/tree.obj").
pub fn get(name: &str) -> Option<&'static [u8]> {
	MODEL_FILES.iter().find(|(n, _)| *n == name).map(|(_, data)| *data)
}
